package com.zomiggy.security;
import com.zomiggy.repository.UserRepository; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.lang.NonNull; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserRepository users; public JwtFilter(JwtService jwt,UserRepository users){this.jwt=jwt;this.users=users;} @Override protected void doFilterInternal(@NonNull HttpServletRequest req,@NonNull HttpServletResponse res,@NonNull FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer "))try{var user=users.findByMobile(jwt.subject(h.substring(7))).orElse(null); if(user!=null)SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(user.getMobile(),null,List.of(new SimpleGrantedAuthority("ROLE_"+user.getRole()))));}catch(RuntimeException ignored){} chain.doFilter(req,res);} }